#!/usr/bin/env python3
"""Plot the CSV generated by serving_sim. Requires matplotlib."""

import csv
import sys
from pathlib import Path

import matplotlib

# Write files in terminal-only environments such as remote Linux hosts.
matplotlib.use("Agg")
import matplotlib.pyplot as plt


def main() -> None:
    if len(sys.argv) != 3:
        raise SystemExit("usage: plot_results.py RESULTS/comparison.csv RESULTS/comparison.png")

    input_path = Path(sys.argv[1])
    output_path = Path(sys.argv[2])
    with input_path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))

    scenarios = [row["scenario"] for row in rows]
    goodput = [float(row["slo_goodput_requests_per_second"]) for row in rows]
    ttft_p95 = [float(row["ttft_p95_ms"]) for row in rows]

    figure, axes = plt.subplots(1, 2, figsize=(9, 3.5))
    axes[0].bar(scenarios, goodput, color="#4c78a8")
    axes[0].set_ylabel("SLO-goodput (req/s)")
    axes[0].set_title("Serving quality")
    axes[1].bar(scenarios, ttft_p95, color="#f58518")
    axes[1].set_ylabel("TTFT p95 (ms)")
    axes[1].set_title("Tail first-token latency")
    figure.tight_layout()
    output_path.parent.mkdir(parents=True, exist_ok=True)
    figure.savefig(output_path, dpi=160)
    plt.close(figure)


if __name__ == "__main__":
    main()
